From 5fbea74c19a44bc2d95575880da7f4ee8aad6a2c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:50:18 +0100
Subject: [PATCH] osd: Make useful for setups with more than two screens

With three or more screens the OSD and applet offered only two-screen
actions, which did nothing. Now they hide extend and mirror, add "Use
all screens", and turn screens on next to each other, not on top.

BUG: 421032
---
 common/osdaction.cpp       | 87 +++++++++++++++++++++++++++++++++-----
 common/osdaction.h         |  3 +-
 osd/osd.cpp                |  4 +-
 osd/osd.h                  |  2 +-
 osd/osdmanager.cpp         |  2 +-
 plasmoid/kscreenapplet.cpp |  6 ++-
 plasmoid/kscreenapplet.h   |  4 +-
 7 files changed, 90 insertions(+), 18 deletions(-)

diff --git a/common/osdaction.cpp b/common/osdaction.cpp
index 0f41f2f9..95e8e158 100644
--- a/common/osdaction.cpp
+++ b/common/osdaction.cpp
@@ -21,23 +21,72 @@

 using namespace KScreen;

-QList<OsdAction> OsdAction::availableActions()
+static QList<OsdAction::Action> moreThanTwoMonitorsAllowedActions = {
+    OsdAction::UseAll,
+    OsdAction::SwitchToExternal,
+    OsdAction::SwitchToInternal,
+    OsdAction::NoAction,
+};
+
+static void enableOutputs(const ConfigPtr &config, const QList<OutputPtr> &outputs)
+{
+    QList<OutputPtr> newlyEnabled;
+    for (const auto &output : outputs) {
+        if (!output->isEnabled()) {
+            output->setEnabled(true);
+            newlyEnabled.append(output);
+        }
+    }
+
+    int right = 0;
+    const auto connectedOutputs = config->connectedOutputs();
+    for (const auto &output : connectedOutputs) {
+        if (output->isEnabled() && !newlyEnabled.contains(output)) {
+            right = std::max(right, output->pos().x() + config->logicalSizeForOutputInt(*output).width());
+        }
+    }
+    for (const auto &output : std::as_const(newlyEnabled)) {
+        output->setPos({right, 0});
+        right += config->logicalSizeForOutputInt(*output).width();
+    }
+}
+
+QList<OsdAction> OsdAction::availableActions(const QSharedPointer<KScreen::Config> &config)
 {
-    return {
-        {SwitchToExternal, i18nd("kscreen_common", "Only use external screen"), QStringLiteral("osd-shutd-laptop")},
+    QList<OsdAction> actions = {
+        {UseAll, i18nd("kscreen_common", "Use all screens"), QStringLiteral("osd-sbs-sright")},
+        {SwitchToExternal,
+         i18ndp("kscreen_common", "Only use external screen", "Only use external screens", config->connectedOutputs().size() - 1),
+         QStringLiteral("osd-shutd-laptop")},
         {SwitchToInternal, i18nd("kscreen_common", "Only use built-in screen"), QStringLiteral("osd-shutd-screen")},
         {Clone, i18nd("kscreen_common", "Mirror screens"), QStringLiteral("osd-duplicate")},
         {ExtendLeft, i18nd("kscreen_common", "Extend to left of built-in screen"), QStringLiteral("osd-sbs-left")},
         {ExtendRight, i18nd("kscreen_common", "Extend to right of built-in screen"), QStringLiteral("osd-sbs-sright")},
         {NoAction, i18nd("kscreen_common", "Leave unchanged"), QStringLiteral("dialog-cancel")},
     };
+
+    if (config->connectedOutputs().size() > 2) {
+        actions.removeIf([](const auto &action) {
+            return !moreThanTwoMonitorsAllowedActions.contains(action.action);
+        });
+    } else {
+        actions.removeIf([](const auto &action) {
+            return action.action == OsdAction::UseAll;
+        });
+    }
+
+    return actions;
 }

 KScreen::SetConfigOperation *OsdAction::applyAction(const QSharedPointer<KScreen::Config> &config, Action action)
 {
     const ConfigPtr copy = config->clone();
     const OutputList outputs = copy->connectedOutputs();
-    if (outputs.size() != 2) {
+    if (outputs.size() < 2) {
+        return nullptr;
+    }
+
+    if (outputs.size() > 2 && !moreThanTwoMonitorsAllowedActions.contains(action)) {
         return nullptr;
     }

@@ -48,11 +97,15 @@ KScreen::SetConfigOperation *OsdAction::applyAction(const QSharedPointer<KScreen
         internalIt = outputs.begin();
     }
     const OutputPtr &internal = *internalIt;
-    const OutputPtr &external = *std::find_if(outputs.cbegin(), outputs.cend(), [&internal](const auto &output) {
-        return output != internal;
+
+    auto externalOutputs = outputs.values();
+    externalOutputs.removeIf([internal](const auto &output) {
+        return output == internal;
     });

-    external->setReplicationSource(0);
+    for (const auto &external : externalOutputs) {
+        external->setReplicationSource(0);
+    }
     internal->setReplicationSource(0);

     switch (action) {
@@ -60,15 +113,21 @@ KScreen::SetConfigOperation *OsdAction::applyAction(const QSharedPointer<KScreen
         return nullptr;
     case KScreen::OsdAction::Action::SwitchToExternal:
         internal->setEnabled(false);
-        external->setEnabled(true);
-        external->setPos(QPoint());
+        enableOutputs(copy, externalOutputs);
+        if (externalOutputs.size() == 1) {
+            externalOutputs[0]->setPos(QPoint());
+        }
         break;
     case KScreen::OsdAction::Action::SwitchToInternal:
         internal->setEnabled(true);
         internal->setPos(QPoint());
-        external->setEnabled(false);
+        for (const auto &external : externalOutputs) {
+            external->setEnabled(false);
+        }
         break;
     case KScreen::OsdAction::Action::Clone: {
+        // If we're here, we know there's exactly one external output
+        const auto &external = externalOutputs[0];
         internal->setEnabled(true);
         external->setEnabled(true);
         // KWin deals with modes, we just set the replication source
@@ -77,6 +136,8 @@ KScreen::SetConfigOperation *OsdAction::applyAction(const QSharedPointer<KScreen
         break;
     }
     case KScreen::OsdAction::Action::ExtendRight: {
+        // If we're here, we know there's exactly one external output
+        const auto &external = externalOutputs[0];
         internal->setEnabled(true);
         external->setEnabled(true);
         internal->setPos(QPoint());
@@ -97,6 +158,8 @@ KScreen::SetConfigOperation *OsdAction::applyAction(const QSharedPointer<KScreen
         break;
     }
     case KScreen::OsdAction::Action::ExtendLeft: {
+        // If we're here, we know there's exactly one external output
+        const auto &external = externalOutputs[0];
         internal->setEnabled(true);
         external->setEnabled(true);
         external->setPos(QPoint());
@@ -116,6 +179,10 @@ KScreen::SetConfigOperation *OsdAction::applyAction(const QSharedPointer<KScreen
         internal->setPos({copy->logicalSizeForOutputInt(*external).width(), 0});
         break;
     }
+    case KScreen::OsdAction::UseAll: {
+        enableOutputs(copy, outputs.values());
+        break;
+    }
     }
     return new KScreen::SetConfigOperation(copy);
 }
